  func: async ({ redis }, { channel }, { trigger }) => {
    const subscriber = redis.duplicate()
    await subscriber.subscribe(channel, (msg) => {
      trigger.invoke({ message: msg })
    })
    return () => subscriber.unsubscribe()
  }
})
